+#include <algorithm>
+#include <cctype>
+#include <sstream>
+#include <string>
+#include <utility>
+
+namespace {
+
+std::string normalize_word(std::string_view word) {
+    std::string normalized;
+    normalized.reserve(word.size());
+
+    for (unsigned char ch : word) {
+        if (std::isalnum(ch) != 0) {
+            normalized.push_back(static_cast<char>(std::tolower(ch)));
+        }
+    }
+
+    return normalized;
+}
+
+std::vector<std::string> tokenize(std::string_view text) {
+    std::vector<std::string> words;
+    std::istringstream stream{std::string{text}};
+
+    for (std::string raw_word; stream >> raw_word;) {
+        std::string word = normalize_word(raw_word);
+        if (!word.empty()) {
+            words.push_back(std::move(word));
+        }
+    }
+
+    return words;
+}
+
+}  // namespace
+
+SearchEngine::SearchEngine() = default;
+
+SearchEngine::~SearchEngine() = default;
+
+Result<void> SearchEngine::add_book(Book book) {
+    const size_t book_id = books.size();
+
+    for (size_t line_id = 0; line_id < book.lines.size(); ++line_id) {
+        const std::vector<std::string> words = tokenize(book.lines[line_id]);
+        for (size_t word_idx = 0; word_idx < words.size(); ++word_idx) {
+            const std::string& word = words[word_idx];
+            inverted_index[word].push_back(Index{
+                .book_id = book_id,
+                .chapter_id = 0,
+                .line = line_id,
+                .word_idx = word_idx,
+            });
+            ++word_counts[word];
+        }
+    }
+
+    books.push_back(std::move(book));
+    return {};
+}
+
+std::optional<std::vector<Index>> SearchEngine::search(std::string_view query) const {
+    std::vector<Index> matches;
+
+    for (const std::string& word : tokenize(query)) {
+        const auto found = inverted_index.find(word);
+        if (found != inverted_index.end()) {
+            matches.insert(matches.end(), found->second.begin(), found->second.end());
+        }
+    }
+
+    if (matches.empty()) {
+        return std::nullopt;
+    }
+
+    std::ranges::sort(matches, {}, [](const Index& index) {
+        return std::tuple{index.book_id, index.chapter_id, index.line, index.word_idx};
+    });
+
+    return matches;
 }
